import { chromium } from "playwright";
import fs from "fs";
const BASE = "http://localhost:3033";
const browser = await chromium.launch();
const out = {};

function describe(el) {
  if (!el) return null;
  return {
    tag: el.tagName,
    id: el.id || null,
    cls: el.className || null,
    tabIndex: el.tabIndex,
    role: el.getAttribute && el.getAttribute("role"),
    visible: !!(el.offsetWidth || el.offsetHeight || el.getClientRects().length),
  };
}

async function focusStyle(page) {
  return page.evaluate(() => {
    const el = document.activeElement;
    if (!el || el === document.body) return { none: true };
    const cs = getComputedStyle(el);
    return {
      tag: el.tagName, id: el.id || null, cls: (el.className || "").toString().slice(0, 60),
      outlineStyle: cs.outlineStyle, outlineWidth: cs.outlineWidth, outlineColor: cs.outlineColor,
      boxShadow: cs.boxShadow, hasVisibleFocus: cs.outlineStyle !== "none" && cs.outlineWidth !== "0px" || cs.boxShadow !== "none",
    };
  });
}

// --- 1. Nav: tab through header from top ---
{
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  await page.goto(BASE + "/nxm", { waitUntil: "networkidle" });
  await page.evaluate(() => document.body.focus());
  const stops = [];
  for (let i = 0; i < 14; i++) {
    await page.keyboard.press("Tab");
    stops.push(await focusStyle(page));
  }
  out.navTabWalk = stops;
  await page.close();
}

// --- 2. Mods search box (#pal-q on /mods) ---
{
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  await page.goto(BASE + "/nxm/mods", { waitUntil: "networkidle" });
  const info = await page.evaluate(() => describeEl(document.querySelector("#pal-q")));
  // fallback inline describe since page.evaluate can't call outer fn
  const exists = await page.$("#pal-q");
  const attrs = exists ? await page.evaluate(() => {
    const el = document.querySelector("#pal-q");
    return { tabIndex: el.tabIndex, disabled: el.disabled, type: el.type };
  }) : null;
  await page.click("body");
  await page.evaluate(() => document.querySelector("#pal-q")?.blur());
  // tab from the element right before it: focus the element, then check style
  await page.evaluate(() => document.querySelector("#pal-q")?.focus());
  const style = await focusStyle(page);
  out.modsSearchBox = { exists: !!exists, attrs, focusStyle: style };
  await page.close();
}

// --- 3. Contact form ---
{
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  await page.goto(BASE + "/nxm/contact", { waitUntil: "networkidle" });
  const fields = await page.evaluate(() => Array.from(document.querySelectorAll("form input, form textarea, form select, form button")).map((e) => ({ tag: e.tagName, id: e.id, type: e.type || null, tabIndex: e.tabIndex })));
  out.contactFormFields = fields;
  // focus first field then tab through all, recording focus style each stop
  if (fields.length) {
    await page.evaluate(() => document.querySelector("form input, form textarea, form select")?.focus());
    const seq = [await focusStyle(page)];
    for (let i = 0; i < fields.length; i++) {
      await page.keyboard.press("Tab");
      seq.push(await focusStyle(page));
    }
    out.contactFormTabWalk = seq;
  }
  await page.close();
}

// --- 4. Game-servers configurator (player-slots range #cfg-pl + search #gx-q) ---
{
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  await page.goto(BASE + "/nxm/game-servers", { waitUntil: "networkidle" });
  for (const sel of ["#gx-q", "#cfg-pl"]) {
    const exists = await page.$(sel);
    if (!exists) { out[`gs_${sel}`] = { exists: false }; continue; }
    const attrs = await page.evaluate((s) => {
      const el = document.querySelector(s);
      return { tabIndex: el.tabIndex, disabled: el.disabled, type: el.type };
    }, sel);
    await page.evaluate((s) => document.querySelector(s)?.focus(), sel);
    const style = await focusStyle(page);
    out[`gs_${sel}`] = { exists: true, attrs, focusStyle: style };
  }
  await page.close();
}

await browser.close();
fs.writeFileSync(new URL("./nxm_keyboard_results.json", import.meta.url), JSON.stringify(out, null, 2));
console.log(JSON.stringify(out, null, 2));

