import { chromium } from "playwright";
import fs from "fs";
const BASE = "http://localhost:3033";

const targets = [
  { page: "/", selectors: [
    { name: "hero-h1", sel: "main h1" },
    { name: "hero-lede", sel: "main h1 ~ p, .lede, main p" },
    { name: "nav-link", sel: "header.nv a.nv-t" },
    { name: "nav-cta-button", sel: ".nv-act .nxm-navcta .nxm-bt" },
  ]},
  { page: "/pricing", selectors: [
    { name: "card-heading", sel: ".au-card h3, .au-card b" },
    { name: "card-body", sel: ".au-card p" },
    { name: "primary-btn", sel: ".nxm-btn .nxm-bt" },
  ]},
  { page: "/about", selectors: [
    { name: "glass-btn", sel: ".nxm-glassbtn .nxm-bt" },
  ]},
];

function luminance([r, g, b]) {
  const f = (c) => { c /= 255; return c <= 0.03928 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4); };
  return 0.2126 * f(r) + 0.7152 * f(g) + 0.0722 * f(b);
}
function parseColor(str) {
  const m = str.match(/rgba?\(([\d.]+),\s*([\d.]+),\s*([\d.]+)(?:,\s*([\d.]+))?\)/);
  if (!m) return null;
  return [Number(m[1]), Number(m[2]), Number(m[3]), m[4] !== undefined ? Number(m[4]) : 1];
}
function composite(fg, bg) {
  // fg over bg, both [r,g,b,a]
  const a = fg[3] + bg[3] * (1 - fg[3]);
  if (a === 0) return [255, 255, 255, 0];
  const c = (i) => (fg[i] * fg[3] + bg[i] * bg[3] * (1 - fg[3])) / a;
  return [c(0), c(1), c(2), a];
}

const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
const out = [];

for (const t of targets) {
  await page.goto(BASE + "/nxm" + (t.page === "/" ? "" : t.page), { waitUntil: "networkidle" });
  for (const s of t.selectors) {
    const res = await page.evaluate((sel) => {
      const el = document.querySelector(sel);
      if (!el) return null;
      const cs = getComputedStyle(el);
      const rect = el.getBoundingClientRect();
      // walk up collecting background colors (with alpha) until opaque
