import { chromium } from "playwright";
import fs from "fs";
const BASE = "http://localhost:3033";
const pages = ["/", "/game-servers", "/compare", "/pricing"];
const RUNS = 2;

const INIT = `
window.__cls = 0;
window.__shifts = [];
try {
  new PerformanceObserver((list) => {
    for (const entry of list.getEntries()) {
      if (!entry.hadRecentInput) {
        window.__cls += entry.value;
        window.__shifts.push({ value: entry.value, time: entry.startTime, sources: (entry.sources||[]).map(s => s.node ? (s.node.tagName + (s.node.className? '.'+String(s.node.className).slice(0,30):'')) : 'unknown') });
      }
    }
  }).observe({ type: "layout-shift", buffered: true });
} catch (e) { window.__clsError = String(e); }
`;

const browser = await chromium.launch();
const out = {};

for (const p of pages) {
  out[p] = [];
  for (let run = 0; run < RUNS; run++) {
    const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
    await page.addInitScript(INIT);
    await page.goto(BASE + "/nxm" + (p === "/" ? "" : p), { waitUntil: "load" });
    // snapshot key element rects at 1s
    await page.waitForTimeout(1000);
    const rects1 = await page.evaluate(() => {
      const els = Array.from(document.querySelectorAll("h1, .au-card, header.nv, main img")).slice(0, 20);
      return els.map((e) => { const r = e.getBoundingClientRect(); return { tag: e.tagName, cls: (e.className||"").toString().slice(0,30), x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height) }; });
    });
    await page.waitForTimeout(2000);
    const rects3 = await page.evaluate(() => {
      const els = Array.from(document.querySelectorAll("h1, .au-card, header.nv, main img")).slice(0, 20);
      return els.map((e) => { const r = e.getBoundingClientRect(); return { tag: e.tagName, cls: (e.className||"").toString().slice(0,30), x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height) }; });
    });
    const cls = await page.evaluate(() => ({ cls: window.__cls, shifts: window.__shifts, error: window.__clsError }));
    const moved = rects1.map((r1, i) => {
      const r3 = rects3[i];
      if (!r3) return null;
      const dx = Math.abs(r1.x - r3.x), dy = Math.abs(r1.y - r3.y), dw = Math.abs(r1.w - r3.w), dh = Math.abs(r1.h - r3.h);
      if (dx > 2 || dy > 2 || dw > 2 || dh > 2) return { tag: r1.tag, cls: r1.cls, from: r1, to: r3 };
      return null;
    }).filter(Boolean);
    out[p].push({ run, clsScore: cls.cls, clsError: cls.error, shiftCount: cls.shifts?.length || 0, topShifts: (cls.shifts||[]).sort((a,b)=>b.value-a.value).slice(0,5), movedBetween1and3s: moved });
    await page.close();
  }
}

await browser.close();
fs.writeFileSync(new URL("./nxm_cls_results.json", import.meta.url), JSON.stringify(out, null, 2));
console.log(JSON.stringify(out, null, 2));

