import { chromium } from "playwright";
import fs from "fs";
const BASE = "http://localhost:3033";
const pages = [
  { path: "/", note: "hero intro word-reveal, aurora drift, orbit" },
  { path: "/compare", note: "split-flap board flip + hero intro" },
  { path: "/matrix", note: "orbit visualization" },
  { path: "/game-servers", note: "hero + configurator chart" },
];

const browser = await chromium.launch();
const out = [];

for (const p of pages) {
  const ctx = await browser.newContext({ reducedMotion: "reduce" });
  const page = await ctx.newPage();
  await page.goto(BASE + "/nxm" + (p.path === "/" ? "" : p.path), { waitUntil: "load" });
  await page.waitForTimeout(1200);
  const snap1 = await page.evaluate(() => {
    const els = Array.from(document.querySelectorAll("h1 .wi, .hero-title, .hero-img, .oc-halo, .oc-ring, .fl-c .ch, .dep-fill, .hbg-aur, .count")).slice(0, 30);
    return els.map((e) => {
      const cs = getComputedStyle(e);
      const r = e.getBoundingClientRect();
      return { sel: e.className.toString().slice(0, 30), text: (e.textContent || "").slice(0, 20), opacity: cs.opacity, transform: cs.transform, animName: cs.animationName, animPlay: cs.animationPlayState, x: Math.round(r.x), y: Math.round(r.y) };
    });
  });
  await page.waitForTimeout(1500);
  const snap2 = await page.evaluate(() => {
    const els = Array.from(document.querySelectorAll("h1 .wi, .hero-title, .hero-img, .oc-halo, .oc-ring, .fl-c .ch, .dep-fill, .hbg-aur, .count")).slice(0, 30);
    return els.map((e) => {
      const cs = getComputedStyle(e);
      const r = e.getBoundingClientRect();
      return { sel: e.className.toString().slice(0, 30), text: (e.textContent || "").slice(0, 20), opacity: cs.opacity, transform: cs.transform, animName: cs.animationName, animPlay: cs.animationPlayState, x: Math.round(r.x), y: Math.round(r.y) };
    });
  });
  const diffs = snap1.map((a, i) => {
    const b = snap2[i];
    if (!b) return null;
    const changed = a.opacity !== b.opacity || a.transform !== b.transform || a.text !== b.text || a.x !== b.x || a.y !== b.y;
    return changed ? { sel: a.sel, before: a, after: b } : null;
  }).filter(Boolean);
  out.push({ page: p.path, note: p.note, elementCount: snap1.length, changedBetweenSnapshots: diffs });
  await ctx.close();
}

await browser.close();
fs.writeFileSync(new URL("./nxm_reducedmotion_results.json", import.meta.url), JSON.stringify(out, null, 2));
console.log(JSON.stringify(out, null, 2));

