// Main pass: console/network errors, internal links, images, headings, mobile scroll.
// Single browser instance, sequential pages (per worktree Playwright rule).
import { chromium } from "playwright";
import fs from "fs";

const BASE = "http://localhost:3033";
const pages = JSON.parse(fs.readFileSync(new URL("./nxm_pages.json", import.meta.url)));
const results = [];
const allInternalLinks = new Set();

const browser = await chromium.launch();

for (const p of pages) {
  const context = await browser.newContext({ viewport: { width: 1440, height: 900 } });
  const page = await context.newPage();
  const consoleErrors = [];
  const pageErrors = [];
  const failedResponses = [];
  const failedRequests = [];

  page.on("console", (msg) => {
    if (msg.type() === "error") consoleErrors.push(msg.text().slice(0, 300));
  });
  page.on("pageerror", (err) => pageErrors.push(String(err).slice(0, 300)));
  page.on("requestfailed", (req) => {
    failedRequests.push(`${req.method()} ${req.url()} -- ${req.failure()?.errorText}`);
  });
  page.on("response", (res) => {
    const status = res.status();
    if (status >= 400) failedResponses.push(`${status} ${res.url()}`);
  });

  let navError = null;
  let data = { navError: null, consoleErrors, pageErrors, failedResponses, failedRequests };
  try {
    try {
      await page.goto(BASE + "/nxm" + (p.path === "/" ? "" : p.path), { waitUntil: "load", timeout: 30000 });
    } catch (e) {
      navError = String(e).slice(0, 300);
    }
    // give client scripts/animations/fonts a moment regardless of load strategy
    await page.waitForTimeout(1200).catch(() => {});
    data.navError = navError;

    // headings, in DOM order, within main content (fall back to body)
    data.headings = await page.evaluate(() => {
      const root = document.querySelector("main") || document.body;
      if (!root) return null;
      return Array.from(root.querySelectorAll("h1,h2,h3,h4,h5,h6")).map((h) => ({
        level: Number(h.tagName[1]),
        text: h.textContent.trim().slice(0, 80),
      }));
    }).catch((e) => ({ error: String(e).slice(0, 200) }));
    data.h1Count = await page.evaluate(() => document.querySelectorAll("h1").length).catch(() => null);

    // images: alt text + broken check
    data.images = await page.evaluate(() => {
      return Array.from(document.querySelectorAll("img")).map((img) => ({
        src: img.getAttribute("src") || img.currentSrc || "",
        alt: img.getAttribute("alt"),
        decorative: img.getAttribute("alt") === "" || img.getAttribute("aria-hidden") === "true",
        naturalWidth: img.naturalWidth,
        complete: img.complete,
        w: img.width,
        h: img.height,
      }));
    }).catch((e) => [{ error: String(e).slice(0, 200) }]);

    // internal links
    const hrefs = await page.evaluate(() => Array.from(document.querySelectorAll("a[href]")).map((a) => a.getAttribute("href"))).catch(() => []);
    data.hrefs = hrefs;
    for (const h of hrefs) {
      if (!h) continue;
      if (h.startsWith("/nxm")) allInternalLinks.add(h);
      else if (h.startsWith("/") && !h.startsWith("//") && !["/register", "/login", "/dashboard", "/admin"].some((x) => h === x || h.startsWith(x + "/") || h.startsWith(x + "?") || h.startsWith(x + "#"))) {
        data.suspectRootLinks = data.suspectRootLinks || [];
        data.suspectRootLinks.push(h);
      }
    }

    // mobile scroll check @390
    await page.setViewportSize({ width: 390, height: 844 });
    await page.waitForTimeout(400).catch(() => {});
    data.mobileScrollWidth = await page.evaluate(() => document.documentElement.scrollWidth).catch(() => null);
    data.mobileClientWidth = await page.evaluate(() => document.documentElement.clientWidth).catch(() => null);
  } catch (e) {
    data.fatalError = String(e).slice(0, 400);
  }

  results.push({ page: p, data });
  console.log(`done: ${p.path} nav=${data.navError ? "FAIL" : "ok"} consoleErr=${consoleErrors.length} pageErr=${pageErrors.length} failedResp=${failedResponses.length} h1=${data.h1Count ?? "-"}`);
  await context.close().catch(() => {});
  // flush progressively so a later crash doesn't lose earlier work
  fs.writeFileSync(new URL("./nxm_audit_results.json", import.meta.url), JSON.stringify(results, null, 2));
}

await browser.close();

fs.writeFileSync(new URL("./nxm_audit_results.json", import.meta.url), JSON.stringify(results, null, 2));
fs.writeFileSync(new URL("./nxm_internal_links.json", import.meta.url), JSON.stringify([...allInternalLinks].sort(), null, 2));
console.log("TOTAL internal links collected:", allInternalLinks.size);

