"use client";

import { useState, type HTMLAttributes } from "react";

/**
 * A ported page's server-rendered markup, pinned to its first render.
 *
 * The design pages are HTML strings the page script then brings to life
 * (typeaheads, poster rows, icons, charts). Any in-place server refresh of the
 * route — e.g. the promo popup's server action setting its visitor cookie on a
 * first visit, which makes Next re-render the page — would otherwise hand
 * React a fresh string and reset innerHTML, wiping everything the script built
 * while the page stays marked as mounted. Keeping the first string means a
 * refresh never touches this subtree (React 19 compares the
 * `{__html}` object by identity, so even an identical string would reset it); a real navigation remounts it anyway.
 */
export function StableHtml({ html, as = "div", ...rest }: { html: string; as?: "div" | "main" } & HTMLAttributes<HTMLElement>) {
  // the SAME object every render: React 19 re-sets innerHTML whenever the
  // dangerouslySetInnerHTML object changes identity, even for an equal string
  const [inner] = useState(() => ({ __html: html }));
  const Tag = as;
  return <Tag {...rest} dangerouslySetInnerHTML={inner} />;
}

