"use client";

import dynamic from "next/dynamic";
import { usePathname } from "next/navigation";
import { useEffect, useState, type ComponentType } from "react";
import { createPortal } from "react-dom";

/**
 * Mounts the LIVE free-tool component into the tool page's panel.
 *
 * The page is design markup (an HTML string, see tools/nxm/native/tools-tool),
 * so the tool is portaled into the element it provides:
 * `<div class="tt-app" data-tool-app="<slug>">`. The components are the live
 * site's own (components/marketing/tools/*) — same endpoints, same logic —
 * and are only restyled by CSS scoped to `.tt-app`. The size calculator is
 * the new site's own UI (ToolSizeCalculator) because it has to end in a real
 * plan with a deploy link. Each tool is its own chunk, loaded only on its page.
 */
const pick = <T extends Record<string, unknown>>(p: Promise<T>, name: keyof T) => p.then((m) => m[name] as ComponentType);
const TOOLS: Record<string, ComponentType> = {
  "base64": dynamic(() => pick(import("@/components/marketing/tools/Base64Tool"), "Base64Tool"), { ssr: false }),
  "dns-lookup": dynamic(() => pick(import("@/components/marketing/tools/DnsTool"), "DnsTool"), { ssr: false }),
  "domain-generator": dynamic(() => pick(import("@/components/marketing/tools/DomainGeneratorTool"), "DomainGeneratorTool"), { ssr: false }),
  "hash-generator": dynamic(() => pick(import("@/components/marketing/tools/HashGeneratorTool"), "HashGeneratorTool"), { ssr: false }),
  "http-headers": dynamic(() => pick(import("@/components/marketing/tools/HttpHeadersTool"), "HttpHeadersTool"), { ssr: false }),
  "json-formatter": dynamic(() => pick(import("@/components/marketing/tools/JsonFormatterTool"), "JsonFormatterTool"), { ssr: false }),
  "latency-test": dynamic(() => pick(import("@/components/marketing/tools/LatencyTestTool"), "LatencyTestTool"), { ssr: false }),
  "minecraft-server-status": dynamic(() => pick(import("@/components/marketing/tools/MinecraftStatusTool"), "MinecraftStatusTool"), { ssr: false }),
  "my-ip": dynamic(() => pick(import("@/components/marketing/tools/MyIpTool"), "MyIpTool"), { ssr: false }),
  "password-generator": dynamic(() => pick(import("@/components/marketing/tools/PasswordGeneratorTool"), "PasswordGeneratorTool"), { ssr: false }),
  "port-checker": dynamic(() => pick(import("@/components/marketing/tools/PortCheckerTool"), "PortCheckerTool"), { ssr: false }),
  "server-size-calculator": dynamic(() => pick(import("./ToolSizeCalculator"), "ToolSizeCalculator"), { ssr: false }),
  "ssl-checker": dynamic(() => pick(import("@/components/marketing/tools/SslCheckerTool"), "SslCheckerTool"), { ssr: false }),
  "subnet-calculator": dynamic(() => pick(import("@/components/marketing/tools/SubnetCalculatorTool"), "SubnetCalculatorTool"), { ssr: false }),
  "uuid-generator": dynamic(() => pick(import("@/components/marketing/tools/UuidGeneratorTool"), "UuidGeneratorTool"), { ssr: false }),
  "whois": dynamic(() => pick(import("@/components/marketing/tools/WhoisTool"), "WhoisTool"), { ssr: false }),
};

export function ToolMount() {
  const pathname = usePathname();
  const [slot, setSlot] = useState<{ host: HTMLElement; slug: string } | null>(null);

  useEffect(() => {
    let layer: HTMLElement | null = null;
    const attach = () => {
      const app = document.querySelector<HTMLElement>(".tt-app[data-tool-app]");
      if (!app) return false;
      const slug = app.dataset.toolApp ?? "";
      if (!TOOLS[slug]) return true; // unknown tool: leave the page's own fallback
      layer = document.createElement("div");
      layer.className = "tt-mount";
      app.appendChild(layer);
      app.classList.add("on");
      setSlot({ host: layer, slug });
      return true;
    };
    // the page markup can stream in after this layout-level effect runs
    let mo: MutationObserver | null = null;
    if (!attach()) {
      mo = new MutationObserver(() => { if (attach()) mo?.disconnect(); });
      mo.observe(document.body, { childList: true, subtree: true });
    }
    return () => {
      mo?.disconnect();
      layer?.parentElement?.classList.remove("on");
      layer?.remove();
      setSlot(null);
    };
  }, [pathname]);

  if (!slot) return null;
  const Tool = TOOLS[slot.slug];
  return createPortal(<Tool />, slot.host);
}

"use client";

import { useState, useTransition } from "react";
import { subscribe, type SubscribeResult } from "@/lib/actions-newsletter";

/**
 * The new footer's email capture. Calls the exact same server action the live
 * footer's box calls (`subscribe` in lib/actions-newsletter.ts) — same
 * validation, same idempotent "already subscribed" handling, same error
 * copy — just markup/classes of its own (the design's own footer has no
 * subscribe form to reuse; see the `.nxm-foot-nl*` rules in nxm.css).
 */
export function NxmNewsletterForm({ source = "nxm-footer" }: { source?: string }) {
  const [email, setEmail] = useState("");
  const [result, setResult] = useState<SubscribeResult | null>(null);
  const [pending, startTransition] = useTransition();

  function onSubmit(e: React.FormEvent) {
    e.preventDefault();
    if (pending) return;
    startTransition(async () => {
      const res = await subscribe(email, source);
      setResult(res);
      if (res.ok) setEmail("");
    });
  }

  if (result?.ok) {
    return (
      <p className="nxm-foot-nlmsg ok" role="status" aria-live="polite">
        {result.message}
      </p>
    );
  }

  return (
    <form onSubmit={onSubmit} noValidate className="nxm-foot-nl">
      <label className="visually-hidden" htmlFor="nxm-foot-email">
        Email address
      </label>
      <div className="nxm-foot-nlf">
        <input
          id="nxm-foot-email"
          type="email"
          name="email"
          autoComplete="email"
          required
          maxLength={200}
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          placeholder="you@example.com"
          aria-invalid={result?.ok === false || undefined}
          disabled={pending}
        />
        <button type="submit" className="nxm-btn nxm-sm" disabled={pending}>
          {pending ? "Subscribing…" : "Subscribe"}
        </button>
      </div>
      {result && !result.ok && (
        <p className="nxm-foot-nlmsg err" role="alert">
          {result.message}
        </p>
      )}
    </form>
  );
}

