 * site's FooterStatus (components/marketing/FooterStatus.tsx): the public
 * `/api/health` probe (in-process cached ~15s server-side), fetched
 * client-side for the same reason it is there — every /nxm page COULD be
 * statically prerendered even though today's pages export
 * `dynamic = "force-dynamic"`, and a status line baked into a shared footer
 * component is exactly the kind of thing that quietly goes stale if that ever
 * changes. Until the probe answers, or if it fails, this says nothing rather
 * than guessing "operational" — the same discipline as the live footer.
 */

type Health = {
  web?: { status: CompStatus };
  db?: { status: CompStatus };
  worker?: { status: CompStatus };
  proxmox?: { status: CompStatus };
};

/** Worst-of roll-up, mirroring `overallStatus()` in lib/monitoring. */
function rollUp(h: Health): CompStatus | null {
  const all = [h.web?.status, h.db?.status, h.worker?.status, h.proxmox?.status];
  if (all.some((s) => s === undefined)) return null;
  if (all.includes("down")) return "down";
  if (all.includes("degraded")) return "degraded";
  return "operational";
}

