import "server-only";
import type { BlogPost } from "@prisma/client";
import { db } from "@/lib/db";
import { getPostsPage, getPublishedPosts, searchPublishedPosts, POSTS_PER_PAGE, APP_URL } from "@/lib/blog";
import type { NxmLoad } from "./lib";
import { coverFor, coverHtml, coverCss } from "./blog-covers";
import { NXM_BASE, categoryLabel, esc, excerptOf, postHref, published, readLabel, shortDate } from "./blog-shared";

/**
 * /blog — the hub, every value from the blog tables at request time:
 * featured posts, "Start here", the latest grid, server-side search (the same
 * `searchPublishedPosts`/`getPostsPage` the live /blog uses — crawlable, and
 * covering every post, not just the ones on screen), category chips with real
 * counts, and pagination with the live page size (so /blog?page=N lists the
 * same posts as the live page N). Every card has its date (publishedAt) and a
 * cover from the cover system (blog-covers.ts).
 */

const HUB = `${NXM_BASE}/blog`;
function hubHref(o: { q?: string; category?: string; page?: number }) {
  const u = new URLSearchParams();
  if (o.q) u.set("q", o.q);
  if (o.category) u.set("category", o.category);
  if (o.page && o.page > 1) u.set("page", String(o.page));
  const s = u.toString();
  return s ? `${HUB}?${s}` : HUB;
}
const parsePage = (v?: string) => {
  const n = Number.parseInt(v ?? "1", 10);
  return Number.isFinite(n) && n > 0 ? n : 1;
};

type Card = Pick<BlogPost, "slug" | "title" | "excerpt" | "body" | "category" | "tags" | "coverImage" | "publishedAt" | "createdAt">;

/** One hub card (design: build_bloghub.py `card`), with its date and a
 *  consistent "Read more". Repeated game art on one page gets the design's
 *  `alt` crop so two guides for the same game don't look identical. */
function card(p: Card, uid: string, cls: string, seenArt: Set<string>, eager = false) {
  const c = coverFor(p);
  let aCls = "bh-a" + (c.kind === "art" ? " svg" : "");
  if (c.kind === "image" && c.source === "game") {
    if (seenArt.has(c.src)) aCls += " alt";
    seenArt.add(c.src);
  }
  const d = published(p);
  return `<a class="${cls}" href="${esc(postHref(p.slug))}"><div class="${aCls}">${coverHtml(c, uid, { eager })}</div>` +
    `<div class="bh-b"><span class="bh-m">${esc(categoryLabel(p.category))} · ${esc(readLabel(p.body))} · <time datetime="${d.toISOString()}">${esc(shortDate(d))}</time></span>` +
    `<h3>${esc(p.title)}</h3><p>${esc(excerptOf(p))}</p><span class="bh-go" aria-hidden="true">Read more →</span></div></a>`;
}

/** Categories with at least one published post, busiest first. */
async function categories() {
  const rows = await db.blogPost.groupBy({ by: ["category"], where: { published: true }, _count: { _all: true } });
