async function startHere(all: BlogPost[]) {
  const pinned = all.filter((p) => p.tags.map((t) => t.toLowerCase()).includes("start-here"));
  const out: BlogPost[] = pinned.slice(0, 4);
  for (const re of FIRST_WEEK) {
    if (out.length >= 4) break;
    const hit = all.find((p) => re.test(p.title) && !out.includes(p));
    if (hit) out.push(hit);
  }

