import { chromium } from "playwright";
const BASE = "http://localhost:3033";
const pages = ["/game-servers", "/web-hosting", "/blog"];
const browser = await chromium.launch();
for (const p of pages) {
  const page = await browser.newPage();
  await page.goto(BASE + "/nxm" + p, { waitUntil: "load" });
  await page.waitForTimeout(600);
  const headings = await page.evaluate(() => {
    const root = document.querySelector("main") || document.body;
    return Array.from(root.querySelectorAll("h1,h2,h3,h4,h5,h6")).map((h) => ({ level: Number(h.tagName[1]), text: h.textContent.trim().slice(0, 50) }));
  });
  let prev = 0, skip = null;
  for (const h of headings) { if (prev && h.level > prev + 1) { skip = `h${prev}->h${h.level} at "${h.text}"`; break; } prev = h.level; }
  const h1s = headings.filter((h) => h.level === 1).length;
  console.log(p, "h1Count=" + h1s, skip || "no skip", JSON.stringify(headings.map((h) => h.level)));
  await page.close();
}
await browser.close();

