1	"use client";
2	
3	/**
4	 * The 7-day trial popup + its persistent countdown bar.
5	 *
6	 * Mounted ONCE on each of the marketing layout and the portal (dashboard)
7	 * layout. Both calls hit the SAME `getPromoPopupState` server action, which
8	 * reads/writes ONE PromoSighting row keyed on one shared identity (the
9	 * logged-in userId, or a dedicated pre-login cookie) — that shared row is the
10	 * entire mechanism behind "see it on one side, don't see it again on the
11	 * other." See lib/actions-promo-trial.ts and PromoSighting's schema comment
12	 * for the server-side half of this.
13	 *
14	 * The countdown itself: the server hands down `secondsLeft` once, computed
15	 * from a `firstSeenAt` timestamp it alone controls; this component just
16	 * ticks a local number down from there every second for a smooth display. A
17	 * page refresh mid-window calls the action again and gets the CORRECT
18	 * remaining time (not a reset new window) — the personal timer cannot be
19	 * extended by reloading or by editing anything visible in the browser. See
20	 * lib/promo-trial.ts's doc comment for why this promo runs a real per-visitor
21	 * window rather than one shared campaign deadline, and Coupon.expiresAt for
22	 * the campaign's own honest, shared 7-day boundary (enforced independently,
23	 * server-side, at redemption — this component has no say in it).
24	 */
25	
26	import Link from "next/link";
27	import { useEffect, useRef, useState } from "react";
28	import { getPromoPopupState, dismissPromoPopup, dismissPromoBar, type PromoPopupState } from "@/lib/actions-promo-trial";
29	
30	function fmt(totalSeconds: number): string {
31	  const h = Math.floor(totalSeconds / 3600);
32	  const m = Math.floor((totalSeconds % 3600) / 60);
33	  const s = totalSeconds % 60;
34	  return `${h}:${String(m).padStart(2, "0")}:${String(s).padStart(2, "0")}`;
35	}
36	
37	/**
38	 * Starting count + floor for the "spots left" ticker below. Explicit,
39	 * informed call (2026-09-22): this number is NOT backed by any real
40	 * capacity limit or redemption count — it decrements on a plain 5s
41	 * interval, identically for every visitor, purely as a scarcity cue. Raised
42	 * as a deceptive-scarcity concern (the FTC's dark-pattern guidance calls
43	 * out fabricated "X left" counters specifically) before building this;
44	 * kept as scripted exactly as requested. If this becomes worth revisiting,
45	 * the real, defensible version is a `CouponRedemption` count against a real
46	 * `Coupon.maxRedemptions` cap — see lib/coupon-redemption.ts.
47	 */
48	const SPOTS_START = 18;
49	const SPOTS_FLOOR = 3;
50	const SPOTS_TICK_MS = 5000;
51	
52	export function PromoTrialPopup() {
53	  const [state, setState] = useState<PromoPopupState | null>(null);
54	  const [open, setOpen] = useState(false);
55	  const [barVisible, setBarVisible] = useState(false);
56	  const [secondsLeft, setSecondsLeft] = useState(0);
57	  const [copied, setCopied] = useState(false);
58	  const [spotsLeft, setSpotsLeft] = useState(SPOTS_START);
59	  const [justDeployed, setJustDeployed] = useState(false);
60	
61	  useEffect(() => {
62	    let alive = true;
63	    getPromoPopupState().then((s) => {
64	      if (!alive) return;
65	      setState(s);
66	      if (s.show) {
67	        setSecondsLeft(s.secondsLeft);
68	        // The modal shows only on its one still-undismissed sighting; every
69	        // later page load (marketing or portal, either one) gets the bar
70	        // instead — see PromoPopupState.mode's doc comment for why this used
71	        // to silently skip the portal entirely.
72	        if (s.mode === "modal") setOpen(true);
73	        else setBarVisible(true);
74	      }
75	    });
76	    return () => {
77	      alive = false;
78	    };
79	  }, []);
80	
81	  useEffect(() => {
82	    if (!open && !barVisible) return;
83	    const t = setInterval(() => {
84	      setSecondsLeft((s) => {
85	        if (s <= 1) {
86	          clearInterval(t);
87	          setOpen(false);
88	          setBarVisible(false);
89	          return 0;
90	        }
91	        return s - 1;
92	      });
93	    }, 1000);
94	    return () => clearInterval(t);
95	  }, [open, barVisible]);
96	
97	  // "Spots left" ticker — see SPOTS_START's doc comment above for what this
98	  // is and isn't. Runs only while the modal itself is open (not the bar).
99	  useEffect(() => {
100	    if (!open) return;
101	    const t = setInterval(() => {
102	      setSpotsLeft((n) => {
103	        if (n <= SPOTS_FLOOR) {
104	          clearInterval(t);
105	          return n;
106	        }
107	        setJustDeployed(true);
108	        setTimeout(() => setJustDeployed(false), 1300);
109	        return n - 1;
110	      });
111	    }, SPOTS_TICK_MS);
112	    return () => clearInterval(t);
113	  }, [open]);
114	
115	  if (!state?.show) return null;
116	
117	  function close() {
118	    setOpen(false);
119	    setBarVisible(true);
120	    void dismissPromoPopup();
121	  }
122	  function dismissBar() {
123	    setBarVisible(false);
124	    void dismissPromoBar();
125	  }
126	  async function copyCode() {
127	    try {
128	      await navigator.clipboard.writeText(state && state.show ? state.code : "");
129	      setCopied(true);
130	      setTimeout(() => setCopied(false), 1600);
131	    } catch {
132	      // Clipboard API unavailable — the code is still selectable text in the box.
133	    }
134	  }
135	
136	  return (
137	    <>
138	      {barVisible && (
139	        <div className="promo-bar">
140	          <span className="promo-bar-pill">🔥 7-DAY TRIAL SALE</span>
141	          <span>
142	            Setup fee only ${(state.setupCents / 100).toFixed(2)} ·{" "}
143	            <span className="mono">{fmt(secondsLeft)}</span> left
144	          </span>
145	          <Link href={state.ctaHref} className="promo-bar-cta">
146	            Claim now →
147	          </Link>
148	          <button className="promo-bar-close" onClick={dismissBar} aria-label="Dismiss">
149	            ✕
150	          </button>
151	        </div>
152	      )}
153	
154	      {open && (
155	        <div className="promo-scrim" role="dialog" aria-modal="true" aria-label="Limited time offer">
156	          <div className="promo-modal">
157	            <button className="promo-modal-close" onClick={close} aria-label="Close">
158	              ✕
159	            </button>
160	
161	            <div className="promo-collage">
162	              <span className="promo-eyebrow">
163	                <span className="promo-dot" /> LIMITED TIME
164	              </span>
165	              <div className="promo-fan">
166	                {/* eslint-disable-next-line @next/next/no-img-element -- small static promo art */}
167	                <img className="promo-poster promo-poster-mc" src="/games/art/minecraft_poster.jpg" alt="Minecraft" />
168	                {/* eslint-disable-next-line @next/next/no-img-element */}
169	                <img className="promo-poster promo-poster-vh" src="/games/art/valheim_poster.jpg" alt="Valheim" />
170	                {/* eslint-disable-next-line @next/next/no-img-element */}
171	                <img className="promo-poster promo-poster-cs" src="/games/art/cs2_poster.jpg" alt="Counter-Strike 2" />
172	              </div>
173	              <div className="promo-bottom-band">
174	                {state.otherGamesCount > 0 && (
175	                  <span className="promo-more-games">+{state.otherGamesCount} more games supported</span>
176	                )}
177	                <div className="promo-svc-row">
178	                  <span className="promo-svc-chip">
179	                    {/* eslint-disable-next-line @next/next/no-img-element */}
180	                    <img src="/nx/svc/game.webp" alt="" />
181	                    <span>Game Servers</span>
182	                  </span>
183	                  <span className="promo-svc-chip">
184	                    {/* eslint-disable-next-line @next/next/no-img-element */}
185	                    <img src="/nx/svc/vps.webp" alt="" />
186	                    <span>Cloud VPS</span>
187	                  </span>
188	                </div>
189	              </div>
190	            </div>
191	
192	            <div className="promo-offer">
193	              <span className="promo-kicker">{state.trialDays}-day free trial</span>
194	              <h2 className="promo-title">
195	                Your first week is <em>on us.</em>
196	              </h2>
197	              <p className="promo-sub">
198	                Deploy any Game Server or Cloud VPS plan. Pay only a{" "}
199	                <b>${(state.setupCents / 100).toFixed(2)} one-time setup fee</b> today — no charges for{" "}
200	                {state.trialDays} days.
201	              </p>
202	
203	              <div className="promo-countdown">
204	                <span className="promo-countdown-lab">Offer expires in</span>
205	                <span className="promo-countdown-num mono">{fmt(secondsLeft)}</span>
206	              </div>
207	
208	              <div className="promo-code-box">
209	                <div>
210	                  <div className="promo-code-lab">Your code</div>
211	                  <div className="promo-code mono">{state.code}</div>
212	                </div>
213	                <button onClick={copyCode} className={copied ? "promo-copy-btn copied" : "promo-copy-btn"}>
214	                  {copied ? "Copied ✓" : "Copy code"}
215	                </button>
216	              </div>
217	
218	              <div className="promo-spots" aria-live="polite">
219	                <span className={justDeployed ? "promo-spots-icon deploying" : "promo-spots-icon"}>
220	                  <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
221	                    <rect x="3" y="4" width="18" height="7" rx="1.5" />
222	                    <rect x="3" y="13" width="18" height="7" rx="1.5" />
223	                    <circle cx="7" cy="7.5" r="1" fill="currentColor" stroke="none" />
224	                    <circle cx="7" cy="16.5" r="1" fill="currentColor" stroke="none" />
225	                  </svg>
226	                </span>
227	                <span key={spotsLeft} className="promo-spots-count">
228	                  Only <b>{spotsLeft}</b> trial spots left today
229	                </span>
230	                {justDeployed && <span className="promo-spots-toast">Server deployed ✓</span>}
231	              </div>
232	
233	              <Link href={state.ctaHref} className="btn-deploy promo-cta" onClick={() => void dismissPromoPopup()}>
234	                Deploy free — claim trial
235	                <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
236	                  <path d="M5 12h14M13 6l6 6-6 6" strokeLinecap="round" strokeLinejoin="round" />
237	                </svg>
238	              </Link>
239	
240	              <p className="promo-fine">
241	                ${(state.setupCents / 100).toFixed(2)} charged once today. Renews automatically at the plan&rsquo;s
242	                standard rate after {state.trialDays} days — cancel anytime before then from your dashboard to avoid
243	                the renewal. New customers only.
244	              </p>
245	              <button className="promo-no-thanks" onClick={close}>
246	                No thanks, I&rsquo;ll pay full price
247	              </button>
248	            </div>
249	          </div>
250	        </div>
251	      )}
252	    </>
253	  );
254	}
