// Modal dialog keyboard contract (2026-09-27 /nxm audit found this open on
// every page with none of it wired up): move focus into the dialog when it
// opens and back to whatever had it once it closes, close on Escape, and
// trap Tab/Shift+Tab inside the dialog's own focusable elements — without
// this, a keyboard user tabs straight through the (visually hidden behind
// the scrim) page underneath, which `aria-modal="true"` promises can't happen.
useEffect(() => {
  if (!open) return;
  previouslyFocused.current = document.activeElement as HTMLElement | null;
  const dlg = dialogRef.current;
  const focusables = dlg ? Array.from(dlg.querySelectorAll<HTMLElement>(FOCUSABLE)) : [];
  (focusables[0] ?? dlg)?.focus();

  function onKeyDown(e: KeyboardEvent) {
    if (e.key === "Escape") {
      e.preventDefault();
      close();
      return;
    }
    if (e.key !== "Tab" || !dlg) return;
    const items = Array.from(dlg.querySelectorAll<HTMLElement>(FOCUSABLE));
    if (items.length === 0) return;
    const first = items[0], last = items[items.length - 1];
    if (e.shiftKey && document.activeElement === first) {
      e.preventDefault();
      last.focus();
    } else if (!e.shiftKey && document.activeElement === last) {
      e.preventDefault();
      first.focus();
    }
  }
  document.addEventListener("keydown", onKeyDown);
  return () => {
    document.removeEventListener("keydown", onKeyDown);
    previouslyFocused.current?.focus?.();
  };
}, [open, close]);

