import "server-only";
import { SEO } from "../_seo/registry";
import GAME_ROUTE_ROWS from "../../../tools/nxm/routes/minecraft-server-hosting.json";
import GAME_LOC_ROWS from "../../../tools/nxm/routes/minecraft-server-hosting-singapore.json";
import LEGAL_ROWS from "../../../tools/nxm/routes/legal.json";
import MIGRATE_FROM_ROWS from "../../../tools/nxm/routes/migrate-from.json";
import TOOLS_TOOL_ROWS from "../../../tools/nxm/routes/tools-tool.json";
import USE_CASE_ROWS from "../../../tools/nxm/routes/use-case.json";
import VPS_VS_ROWS from "../../../tools/nxm/routes/vps-vs-digitalocean.json";
import SERVER_DIR_ROWS from "../../../tools/nxm/routes/server-directory.json";

type RouteRow = { route: string };
const routesOf = (rows: unknown) => (rows as RouteRow[]).map((r) => r.route);

/**
 * Every FIXED production route the new site (/nxm) actually serves — the one
 * place this is computed, from the exact same fan-out JSONs tools/nxm/
 * port_pages.py reads to generate those routes' page files. Any internal
 * link the system builds at request time (a blog post's own in-body links
 * via articleHtml() in blog-article.ts, a location-landing "nearby city"
 * link, …) should stay inside /nxm for a route in this set, or in production
 * for anything else.
 *
 * Before 2026-09-27 this was two independent, hand-typed allowlists
 * (app/nxm/_data/blog-shared.ts and app/nxm/_data/location-landing.ts) that
 * had already drifted apart — blog-shared's covered 3 of the 51 individual
 * game-hosting routes (e.g. /rust-server-hosting, /left-4-dead-2-server-
 * hosting), so a blog post's own "Nxeon's <Game> server hosting…" in-body
 * link — on nearly every game-related post — silently dropped a visitor
 * reading the new site onto the OLD live page instead. One list, imported by
 * both, can't drift the same way again.
 */
export const PORTED_ROUTES = new Set<string>([
  ...Object.keys(SEO),
  ...routesOf(GAME_ROUTE_ROWS),
  ...routesOf(GAME_LOC_ROWS),
  ...routesOf(LEGAL_ROWS),
  ...routesOf(MIGRATE_FROM_ROWS),
  ...routesOf(TOOLS_TOOL_ROWS),
  ...routesOf(USE_CASE_ROWS),
  ...routesOf(VPS_VS_ROWS),
  ...routesOf(SERVER_DIR_ROWS),
]);

/** Dynamic per-item sections (a route per DB row, not a fixed fan-out list). */
const PORTED_PREFIXES = ["/blog/", "/mods/", "/minecraft-server-hosting/"];

export function isPorted(path: string): boolean {
  return PORTED_ROUTES.has(path) || PORTED_PREFIXES.some((p) => path.startsWith(p));
}

